import {validateRecovery} from './recovery-data.js';
export {validateRecovery,fulfillmentCsv,recoveryEnvelope} from './recovery-data.js';
const errors={proof_files:'An attached payment proof could not be copied. The previous verified backup remains available.',access:'Google access was denied. Check sharing on the spreadsheet and both proof archives.',api_disabled:'Enable Google Sheets and Drive API for the connected project.',quota:'Google temporarily limited requests. The scheduled backup will retry.',configuration:'The Google connection or backup tabs need attention.',too_large:'The backup exceeds its size limit. Download recovery data and arrange additional proof storage.',readback:'The saved copy could not be verified. The previous verified backup is preserved.',network:'The last backup could not finish. It will retry automatically.'};
export function mountBackup(root,{api,owner,esc}){
 if(!owner){root.innerHTML='<p class="notice">Only the shop owner can download order backups.</p>';return;}
 root.innerHTML=`<div class="backup-view"><div class="view-heading"><div><span class="eyebrow">PROTECT YOUR ORDERS</span><h1>Backups</h1><p>Keep a copy of orders that still need to be served.</p></div><button class="button button-secondary" data-drive-refresh>Refresh status</button></div><p class="backup-feedback" data-backup-feedback role="status" aria-live="polite">Loading backup status…</p>
 <div class="backup-grid"><section class="panel backup-panel"><h2>Google Drive backup</h2><p>Paid orders and payments under review, still awaiting fulfillment. Includes orders waiting for your payment check and overdue orders. Completed, cancelled and refunded orders leave the active sheet on the next successful sync.</p><dl class="backup-status" data-drive-status aria-label="Automatic backup status"><div><dt>Status</dt><dd>Checking…</dd></div></dl><p class="help-text">Checks every five minutes, even when this dashboard is closed. Unchanged data is skipped; a daily refresh repairs accidental sheet edits.</p><div class="row-actions"><a class="button button-secondary" data-drive-open hidden target="_blank" rel="noopener noreferrer">Open backup sheet</a><a class="button button-secondary" data-proof-open hidden target="_blank" rel="noopener noreferrer">Open proof ZIP</a><button class="button" data-drive-sync disabled>Back up now</button></div></section>
 <section class="panel backup-panel"><h2>Download a copy</h2><p>Save a current snapshot to your device whenever you need it.</p><label for="backup-scope">Orders to include</label><select id="backup-scope"><option value="paid_review">Paid or under-review orders to serve</option><option value="all_unserved">All unserved orders, including unpaid</option></select><p class="help-text backup-count" data-backup-count aria-live="polite">Counting orders…</p><div class="row-actions backup-downloads"><button class="button" data-backup-format="zip">Download with proofs (ZIP)</button><button class="button button-secondary" data-backup-format="xlsx">Download Excel</button><button class="button button-secondary" data-backup-format="json">Download recovery data</button></div><p>The ZIP includes recovery data and actual proof images grouped by order number. Excel includes order details, flavors and a recovery-data tab. The JSON file keeps structured order, payment, history and inventory reservation records.</p><p data-backup-status role="status" aria-live="polite"></p></section></div>
 <section class="panel backup-panel backup-explanation"><h2>What this protects</h2><p>This is an operational copy for recovering unserved orders. It supplements your database backups. Keep downloaded files private because they contain customer details.</p><p>Actual payment-proof images are saved in the private ZIP beside your Google spreadsheet. The manual ZIP also includes images; Excel and JSON contain file paths only. Customer access links are excluded. This is not a full website or database restore. Changes made in Google Sheets do not change website orders.</p><p class="help-text">Paid-order and affiliate history remains in the recovery data after orders are completed. Automatic backup keeps earlier data snapshots for 30 days and alternates between the current and previous proof ZIP. Older snapshots do not guarantee older proof images are still available. Affiliate payout-proof images are not included. Under review does not mean payment is confirmed.</p></section></div>`;
 const q=s=>root.querySelector(s),feedback=q('[data-backup-feedback]'),status=q('[data-backup-status]'),count=q('[data-backup-count]'),drive=q('[data-drive-status]'),refreshButton=q('[data-drive-refresh]'),sync=q('[data-drive-sync]'),scope=q('#backup-scope'),formats=[...root.querySelectorAll('[data-backup-format]')];
 const alive=()=>root.contains(status);let busy=false,syncBusy=false,connection=null,sequence=0,currentActive=null;
 const date=value=>value&&Number.isFinite(Date.parse(value))?new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'No successful copy yet';
 function renderConnection(v){connection=v;const labels={disconnected:'Not connected',pending:'Waiting for first copy',connected:v.pending?'Changes waiting':'Up to date',stale:'Needs attention',error:'Backup failed'};
 const rows=[['Status',labels[v.state]||'Status unavailable'],['Paid / under review to serve',currentActive??'—'],['Last successful copy',date(v.last_success_at)],['Orders in last copy',v.active_count??'—'],['Proof images in last copy',v.proof_count??'—']];drive.innerHTML=rows.map(([k,value])=>'<div><dt>'+esc(k)+'</dt><dd'+(k==='Paid / under review to serve'?' data-current-count':'')+'>'+esc(value)+'</dd></div>').join('');sync.disabled=!v.enabled||syncBusy||v.busy;
 const sheet=q('[data-drive-open]'),proof=q('[data-proof-open]');sheet.hidden=!v.spreadsheet_id;proof.hidden=!v.proof_archive_id;if(v.spreadsheet_id)sheet.href='https://docs.google.com/spreadsheets/d/'+encodeURIComponent(v.spreadsheet_id)+'/edit';if(v.proof_archive_id)proof.href='https://drive.google.com/file/d/'+encodeURIComponent(v.proof_archive_id)+'/view';if(v.state==='error')feedback.textContent=errors[v.last_error]||errors.network;else if(v.state==='stale')feedback.textContent='Changes have waited more than 15 minutes. Download a current copy while the automatic backup retries.';
 }
 const countText=data=>data.active_count+' '+(data.active_count===1?'unserved order':'unserved orders')+' in this selection.';
 async function readCount(){const ticket=++sequence,selected=scope.value;count.textContent='Counting orders…';try{const data=validateRecovery(await api('manual_order_recovery',{scope:selected}));if(alive()&&ticket===sequence){count.textContent=countText(data);const ids=new Set(data.active_order_ids);currentActive=[...data.paid_orders,...(data.review_orders||[])].filter(o=>ids.has(o.id)).length;const cell=drive.querySelector('[data-current-count]');if(cell)cell.textContent=currentActive;}}catch{if(alive()&&ticket===sequence)count.textContent='Order count unavailable. A download will try again.';}}
 async function refresh(){if(refreshButton.disabled)return;refreshButton.disabled=true;feedback.textContent='Refreshing backup status…';await Promise.all([readCount(),(async()=>{try{const v=await api('order_backup_status');if(alive()){feedback.textContent='Status refreshed. Times are shown in Asia/Manila.';renderConnection(v);}}catch{if(alive())feedback.textContent='Backup status could not load. Manual downloads remain available.';}})()]);refreshButton.disabled=false;}
 refreshButton.onclick=refresh;scope.onchange=()=>{status.textContent='';void readCount();};sync.onclick=async()=>{if(syncBusy)return;syncBusy=true;sync.disabled=true;feedback.textContent='Requesting a fresh backup…';try{const v=await api('order_backup_sync_now');if(alive()){if(v?.state)renderConnection(v);feedback.textContent='Backup requested. Refresh status shortly to confirm it finished.';}}catch(e){if(alive())feedback.textContent=e.message||'The backup request failed. Please try again.';}finally{syncBusy=false;if(alive())sync.disabled=!connection?.enabled;}};
 const download=(bytes,type,extension,at)=>{const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download='elio-order-recovery-'+at.replace(/[:.]/g,'-')+'.'+extension;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);};
 for(const button of formats)button.onclick=async()=>{if(busy)return;busy=true;scope.disabled=true;formats.forEach(b=>b.disabled=true);const selected=scope.value,format=button.dataset.backupFormat;status.textContent='Reading current orders and recovery records…';try{const data=validateRecovery(await api('manual_order_recovery',{scope:selected}));const exports=await import('./backup-export.js');let bytes,type;if(format==='zip'){const result=await exports.recoveryZip(data,api,{onProgress:message=>{if(alive())status.textContent=message;}});bytes=result.bytes;type='application/zip';}else if(format==='xlsx'){status.textContent='Preparing Excel workbook…';bytes=await exports.recoveryExcel(data);type='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';}else{bytes=await exports.recoveryJson(data);type='application/json';}if(!alive())return;download(bytes,type,format,data.generated_at);count.textContent=countText(data);status.textContent='Download prepared '+date(data.generated_at)+' · Manila time. Keep this file private.';}catch(e){if(alive())status.textContent=errors[e.code]||e.message||'The backup could not be downloaded. Try again.';}finally{busy=false;scope.disabled=false;formats.forEach(b=>b.disabled=false);}};
 void refresh();
}
